/**
 * Ribbon — a closed tape with a square cross-section, swept by hand along a
 * curve. Each of the four faces carries its own band of a runtime-generated
 * marquee texture (labels lifted from HeroComponent.marqueeItems).
 *
 * Shared by ribbon.html and layout.html — this is the only copy.
 *
 * ES module, so the folder has to be served over http; file:// blocks module
 * imports outright:
 *     cd spike && python3 -m http.server 8000
 */

import * as THREE from "three";

/* ------------------------------------------------------------------ *
 * Content — lifted verbatim from src/app/features/home/hero/hero.ts
 * (HeroComponent.marqueeItems). Same wording, order and casing.
 * The square section has 4 faces and the marquee has 5 items, so the
 * first four are used; swap in "UI / UX DESIGNER" + aztec/7.png here
 * if you want that one on the tape instead.
 * ------------------------------------------------------------------ */

// Alpha masks of public/aztec/{9,2,4,3}.png, inlined as white-on-black
// greyscale so the page still works over file:// (a file:// <img> would
// taint the canvas and make the WebGL texture upload throw). The full
// colour originals sit next to this file as 9.png / 2.png / 4.png / 3.png.
const ICONS = {
	"9": "data:image/png;base64,",
	"2": "data:image/png;base64,",
	"4": "data:image/png;base64,",
	"3": "data:image/png;base64,"
};

const ROWS = [
	{ icon: ICONS["9"], label: "ANGULAR DEVELOPER" },
	{ icon: ICONS["2"], label: "FRONTEND DEVELOPER" },
	{ icon: ICONS["4"], label: "FULLSTACK DEVELOPER" },
	{ icon: ICONS["3"], label: "WEB DESIGNER" }
];

/* ------------------------------------------------------------------ *
 * Tunables
 * ------------------------------------------------------------------ */

const TEX_W = 4096;
const TEX_H = 1024;
const ROW_H = TEX_H / 4; // 256px per face

// .splitter__label: font-weight 700, --font-sans, letter-spacing .025em
const FONT_STACK = '"Inter Tight", -apple-system, system-ui, sans-serif';
const FONT_WEIGHT = 700;
const FONT_SIZE = 148; // base size — rows flex around it, see solveRow
const TRACKING_EM = 0.025;
const ICON_BOX = ROW_H; // icons keep their original square framing
const GAP = 82; // icon <-> text, identical on all four faces

// Tape albedo. The spec put #0a0a0a on the material and pure black in the
// canvas, but MeshStandardMaterial multiplies color * map — that crushes
// the white text to #0a0a0a too and nothing is readable. So the tape
// colour lives in the canvas background instead and the material stays
// white. Same end result: albedo #0a0a0a for the tape, #fff for the text.
const TAPE_COLOR = "#0a0a0a";
const INK_COLOR = "#ffffff";

const SEGMENTS = 400; // rings along the curve
const RIBBON_W = 0.35; // square profile edge length
const U_REPEAT = 8; // texture repeats along the length

// Torus knot (p=2, q=3). KNOT_R is picked so the arc length lands on
// ~44.8 units: at RIBBON_W 0.35 and U_REPEAT 8 that makes the texture
// pixel density identical along u and v, i.e. undistorted lettering.
// (repeats = length / (16 * RIBBON_W) — see the console readout.)
const KNOT_P = 2;
const KNOT_Q = 3;
const KNOT_R = 2.8;

/* ------------------------------------------------------------------ *
 * Texture
 * ------------------------------------------------------------------ */

async function loadImage(src) {
	const img = new Image();
	img.src = src;
	await img.decode();
	return img;
}

function setFont(ctx, px) {
	ctx.font = `${FONT_WEIGHT} ${px}px ${FONT_STACK}`;
	ctx.textAlign = "left";
	ctx.textBaseline = "alphabetic";
}

// Canvas2D letterSpacing is not everywhere yet — fall back to per-glyph
// placement so tracking matches the CSS either way.
const NATIVE_TRACKING = (() => {
	const c = document.createElement("canvas").getContext("2d");
	return "letterSpacing" in c;
})();

function applyTracking(ctx, px) {
	if (NATIVE_TRACKING) ctx.letterSpacing = `${TRACKING_EM * px}px`;
}

function measureText(ctx, text, px) {
	applyTracking(ctx, px);
	if (NATIVE_TRACKING) return ctx.measureText(text).width;
	let w = 0;
	for (const ch of text) w += ctx.measureText(ch).width + TRACKING_EM * px;
	return w;
}

function drawTracked(ctx, text, x, y, px) {
	applyTracking(ctx, px);
	if (NATIVE_TRACKING) {
		ctx.fillText(text, x, y);
		return;
	}
	let cx = x;
	for (const ch of text) {
		ctx.fillText(ch, cx, y);
		cx += ctx.measureText(ch).width + TRACKING_EM * px;
	}
}

/**
 * Lay out one row.
 *
 * The row has to hold a whole number of icon+label units across the full
 * 4096px, otherwise the pattern breaks where the texture wraps in u. The
 * labels are different lengths, so something has to absorb the slack.
 * Letting it land in the gaps is what made the faces disagree so badly
 * (82px on one, 1067px on the next), because the eye compares the
 * icon-to-text distance directly across the edge of the tape.
 *
 * So GAP is fixed and the font size gives instead: the row takes the
 * repeat count that lands nearest the base size, then the size is solved
 * so the units fill 4096 exactly. Costs ~15% size spread between the
 * longest and shortest label, which reads as nothing.
 */
function solveRow(ctx, label, iconW) {
	setFont(ctx, FONT_SIZE);
	const baseW = measureText(ctx, label, FONT_SIZE);

	let best = null;
	for (let n = 1; n <= 6; n++) {
		const avail = TEX_W / n - iconW - 2 * GAP;
		if (avail <= 0) continue;
		const scale = avail / baseW;
		const off = Math.abs(Math.log(scale)); // symmetric up/down
		if (!best || off < best.off) best = { off, n, size: FONT_SIZE * scale };
	}

	// Re-measure at the solved size: text width is linear in font size but
	// not exactly, so the sub-pixel remainder goes back into the gap. Keeps
	// the tiling exact while leaving the gaps equal to well under a pixel.
	const size = best.size;
	setFont(ctx, size);
	const textW = measureText(ctx, label, size);
	const gap = (TEX_W - best.n * (iconW + textW)) / (2 * best.n);
	return { n: best.n, size, gap };
}

async function buildTexture() {
	await document.fonts.load(`${FONT_WEIGHT} ${FONT_SIZE}px "Inter Tight"`);
	await document.fonts.ready;

	const images = await Promise.all(ROWS.map(r => loadImage(r.icon)));

	const canvas = document.createElement("canvas");
	canvas.width = TEX_W;
	canvas.height = TEX_H;
	const ctx = canvas.getContext("2d");

	ctx.fillStyle = TAPE_COLOR;
	ctx.fillRect(0, 0, TEX_W, TEX_H);

	ROWS.forEach((row, r) => {
		const top = r * ROW_H;
		const cy = top + ROW_H / 2;
		const img = images[r];
		const iconW = ICON_BOX * (img.width / img.height);

		const { n, size, gap } = solveRow(ctx, row.label, iconW);
		const unit = TEX_W / n;

		// Centre on the glyph ink, not on the em box — uppercase only,
		// so this puts the cap height dead centre in the 256px strip.
		setFont(ctx, size);
		const m = ctx.measureText(row.label);
		const baseline =
			cy + (m.actualBoundingBoxAscent - m.actualBoundingBoxDescent) / 2;

		console.log(
			`row ${r} "${row.label}" — ${n}x, font ${size.toFixed(1)}px, ` +
				`gap ${gap.toFixed(2)}px`
		);

		for (let i = 0; i < n; i++) {
			const x0 = i * unit;
			const iconX = x0 + gap / 2;
			const textX = iconX + iconW + gap;

			// Additive blend: the mask's black surround leaves the tape
			// colour untouched, the white ink saturates to pure white.
			ctx.globalCompositeOperation = "lighter";
			ctx.drawImage(img, iconX, cy - ICON_BOX / 2, iconW, ICON_BOX);
			ctx.globalCompositeOperation = "source-over";

			ctx.fillStyle = INK_COLOR;
			setFont(ctx, size);
			drawTracked(ctx, row.label, textX, baseline, size);
		}
	});

	const tex = new THREE.CanvasTexture(canvas);
	tex.colorSpace = THREE.SRGBColorSpace;
	// Textures are flipped on upload by default, which would put canvas
	// row 0 at v 0.75-1.0 and stand every glyph on its head. Off, so
	// v 0.0-0.25 really is the first row and the text reads upright.
	tex.flipY = false;
	tex.wrapS = THREE.RepeatWrapping; // u tiles, v stays inside its strip
	tex.wrapT = THREE.ClampToEdgeWrapping;
	tex.needsUpdate = true;
	return tex;
}

/* ------------------------------------------------------------------ *
 * Curve
 * ------------------------------------------------------------------ */

function torusKnotPoint(u) {
	const cu = Math.cos(u);
	const su = Math.sin(u);
	const quOverP = (KNOT_Q / KNOT_P) * u;
	const cs = Math.cos(quOverP);
	return new THREE.Vector3(
		KNOT_R * (2 + cs) * 0.5 * cu,
		KNOT_R * (2 + cs) * 0.5 * su,
		KNOT_R * Math.sin(quOverP) * 0.5
	);
}

function buildCurve() {
	const controls = [];
	const count = 512;
	for (let i = 0; i < count; i++) {
		controls.push(torusKnotPoint((2 * Math.PI * KNOT_P * i) / count));
	}
	const curve = new THREE.CatmullRomCurve3(controls, true, "catmullrom", 0.5);
	curve.arcLengthDivisions = 4000; // control-point density needs a fine cache
	return curve;
}

/* ------------------------------------------------------------------ *
 * Geometry — square-section sweep, built by hand (no TubeGeometry)
 *
 * Per ring: 4 faces x 2 corners = 8 vertices. Corners are duplicated per
 * face so each face carries its own flat normal and its own horizontal
 * band of the texture:
 *
 *      p1 ---- f0 ---- p0        f0: +B   v 0.00 - 0.25
 *      |                |        f1: -N   v 0.25 - 0.50
 *      f1              f3        f2: -B   v 0.50 - 0.75
 *      |                |        f3: +N   v 0.75 - 1.00
 *      p2 ---- f2 ---- p3
 *
 * Options:
 *   segments  rings along the curve
 *   width     square profile edge length
 *   uRepeat   texture repeats along the length — aspectRepeats() picks the
 *             value that keeps the lettering undistorted
 *   closed    whether the curve loops; open curves get no seam snap and are
 *             left uncapped, so run their ends off-screen
 *   twist     extra roll of the profile, in whole turns over the full length
 * ------------------------------------------------------------------ */

function buildRibbonGeometry(curve, options = {}) {
	const {
		segments = SEGMENTS,
		width = RIBBON_W,
		uRepeat = U_REPEAT,
		closed = true,
		twist = 0
	} = options;

	const frames = curve.computeFrenetFrames(segments, closed);
	const half = width / 2;
	const rings = segments + 1;

	const positions = new Float32Array(rings * 8 * 3);
	const normals = new Float32Array(rings * 8 * 3);
	const uvs = new Float32Array(rings * 8 * 2);
	const indices = [];

	const P = new THREE.Vector3();
	const N = new THREE.Vector3();
	const B = new THREE.Vector3();
	const T = new THREE.Vector3();
	const corner = new THREE.Vector3();
	const faceN = new THREE.Vector3();

	// Profile corners in (normal, binormal) coordinates, going around.
	const CORNER = [
		[+1, +1], // p0
		[-1, +1], // p1
		[-1, -1], // p2
		[+1, -1] // p3
	];
	// Outward normal of the face that starts at corner f.
	const FACE_N = [
		[0, +1], // f0 -> +B
		[-1, 0], // f1 -> -N
		[0, -1], // f2 -> -B
		[+1, 0] // f3 -> +N
	];

	for (let i = 0; i < rings; i++) {
		const t = i / segments;
		curve.getPointAt(t, P);
		N.copy(frames.normals[i]);
		B.copy(frames.binormals[i]);

		// Roll the profile around the tangent on top of the Frenet frame.
		if (twist !== 0) {
			const angle = twist * Math.PI * 2 * t;
			curve.getTangentAt(t, T);
			N.applyAxisAngle(T, angle);
			B.applyAxisAngle(T, angle);
		}

		const u = t * uRepeat;

		for (let f = 0; f < 4; f++) {
			faceN
				.set(0, 0, 0)
				.addScaledVector(N, FACE_N[f][0])
				.addScaledVector(B, FACE_N[f][1]);

			for (let c = 0; c < 2; c++) {
				const [kn, kb] = CORNER[(f + c) % 4];
				corner
					.copy(P)
					.addScaledVector(N, kn * half)
					.addScaledVector(B, kb * half);

				const vi = i * 8 + f * 2 + c;
				positions[vi * 3] = corner.x;
				positions[vi * 3 + 1] = corner.y;
				positions[vi * 3 + 2] = corner.z;

				normals[vi * 3] = faceN.x;
				normals[vi * 3 + 1] = faceN.y;
				normals[vi * 3 + 2] = faceN.z;

				uvs[vi * 2] = u;
				uvs[vi * 2 + 1] = (f + c) * 0.25;
			}
		}
	}

	// Arc-length lookup leaves the wrap ring a fraction off ring 0 — snap it
	// so the loop closes exactly. UVs stay at u = uRepeat. Only valid for a
	// closed curve whose twist lands back on itself: a fractional twist ends
	// the profile somewhere else and snapping would kink it.
	if (closed && twist % 1 === 0) {
		for (let k = 0; k < 24; k++) {
			positions[segments * 24 + k] = positions[k];
			normals[segments * 24 + k] = normals[k];
		}
	}

	for (let i = 0; i < segments; i++) {
		const a0 = i * 8;
		const b0 = (i + 1) * 8;
		for (let f = 0; f < 4; f++) {
			const a = a0 + f * 2; // ring i, corner f
			const b = a0 + f * 2 + 1; // ring i, corner f+1
			const c = b0 + f * 2 + 1; // ring i+1, corner f+1
			const d = b0 + f * 2; // ring i+1, corner f
			indices.push(a, b, d, b, c, d); // CCW seen from outside
		}
	}

	const geom = new THREE.BufferGeometry();
	geom.setAttribute("position", new THREE.BufferAttribute(positions, 3));
	geom.setAttribute("normal", new THREE.BufferAttribute(normals, 3));
	geom.setAttribute("uv", new THREE.BufferAttribute(uvs, 2));
	geom.setIndex(indices);
	geom.computeBoundingSphere();
	return geom;
}

/* ------------------------------------------------------------------ *
 * Material — the tape look, so both pages light it identically.
 * ------------------------------------------------------------------ */

export function createTapeMaterial(overrides = {}) {
	return new THREE.MeshStandardMaterial({
		color: 0xffffff, // tape colour is baked into the map, see TAPE_COLOR
		roughness: 0.65,
		metalness: 0.1,
		side: THREE.FrontSide,
		...overrides
	});
}

/**
 * Repeat count at which the texture's pixel density matches along u and v,
 * i.e. the lettering comes out undistorted. A row is TEX_H/4 tall and TEX_W
 * wide, so that lands on length / (16 * width) for any curve.
 */
export function aspectRepeats(length, width) {
	return length / ((TEX_W / (TEX_H / 4)) * width);
}

export {
	ICONS,
	ROWS,
	TEX_W,
	TEX_H,
	ROW_H,
	FONT_STACK,
	FONT_WEIGHT,
	FONT_SIZE,
	TRACKING_EM,
	ICON_BOX,
	GAP,
	TAPE_COLOR,
	INK_COLOR,
	SEGMENTS,
	RIBBON_W,
	U_REPEAT,
	KNOT_P,
	KNOT_Q,
	KNOT_R,
	buildTexture,
	torusKnotPoint,
	buildCurve,
	buildRibbonGeometry
};
